-- Generated from current JSON/SQLite app storage in Raspberry_Machine
SET NAMES utf8mb4;
SET time_zone = "+00:00";
CREATE DATABASE IF NOT EXISTS `rpimachineapp_db` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `rpimachineapp_db`;

CREATE TABLE IF NOT EXISTS `app_client_settings` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `server_url` VARCHAR(255) NULL,
  `client_id` VARCHAR(100) NULL,
  `scanner_mode` VARCHAR(50) NULL,
  `scanner_com_port` VARCHAR(50) NULL,
  `scanner_baudrate` INT NULL,
  `scanner_timeout` DECIMAL(10,3) NULL,
  `raw_json` JSON NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `app_server_settings` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `theme` VARCHAR(100) NULL,
  `qrgen_base_url` VARCHAR(255) NULL,
  `raw_json` JSON NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `app_job_api_config` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `base_url` VARCHAR(255) NULL,
  `user_name` VARCHAR(255) NULL,
  `password_text` VARCHAR(255) NULL,
  `bearer_token` TEXT NULL,
  `token_expires_at_epoch` BIGINT NULL,
  `ttl_seconds` BIGINT NULL,
  `force_new_token` TINYINT NOT NULL DEFAULT 0,
  `username` VARCHAR(255) NULL,
  `raw_json` JSON NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `app_product_api_config` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `provider_key` VARCHAR(100) NOT NULL,
  `base_url` VARCHAR(255) NULL,
  `username` VARCHAR(255) NULL,
  `password_text` VARCHAR(255) NULL,
  `ttl_seconds` BIGINT NULL,
  `force_new_token` TINYINT NOT NULL DEFAULT 0,
  `raw_json` JSON NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_product_api_provider` (`provider_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `app_product_catalog_cache` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `saved_at_utc` VARCHAR(50) NULL,
  `item_count` INT NULL,
  `raw_json` JSON NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `app_product_catalog_items` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `catalog_cache_id` BIGINT NULL,
  `product_id` VARCHAR(50) NOT NULL,
  `name` VARCHAR(255) NULL,
  `sku` VARCHAR(255) NULL,
  `raw_json` JSON NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_product_catalog_product_id` (`product_id`),
  CONSTRAINT `fk_product_catalog_items_cache`
    FOREIGN KEY (`catalog_cache_id`) REFERENCES `app_product_catalog_cache` (`id`)
    ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `app_user_qr_profiles` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `id_number` VARCHAR(100) NOT NULL,
  `name` VARCHAR(255) NULL,
  `role` VARCHAR(100) NULL,
  `created_at_utc` VARCHAR(50) NULL,
  `print_count` INT NOT NULL DEFAULT 0,
  `last_printed_at_utc` VARCHAR(50) NULL,
  `raw_json` JSON NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_user_qr_profiles_id_number` (`id_number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `app_daily_role_assignments` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `assignment_date` DATE NOT NULL,
  `badge_id` VARCHAR(100) NOT NULL,
  `name` VARCHAR(255) NULL,
  `rights` VARCHAR(50) NULL,
  `company_role` VARCHAR(100) NULL,
  `extra_privilege` VARCHAR(100) NULL,
  `updated_at_utc` VARCHAR(50) NULL,
  `raw_json` JSON NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_daily_role_assignment` (`assignment_date`, `badge_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `app_machine_status_overrides` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `machine_code` VARCHAR(50) NOT NULL,
  `status` VARCHAR(100) NOT NULL,
  `reason` TEXT NULL,
  `updated_at_utc` VARCHAR(50) NULL,
  `started_at_utc` VARCHAR(50) NULL,
  `set_by_badge` VARCHAR(100) NULL,
  `set_by_name` VARCHAR(255) NULL,
  `set_by_role` VARCHAR(100) NULL,
  `raw_json` JSON NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_machine_status_overrides_machine_code` (`machine_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `app_machine_status_archive` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `machine_code` VARCHAR(50) NOT NULL,
  `machine_name` VARCHAR(255) NULL,
  `status` VARCHAR(100) NOT NULL,
  `reason` TEXT NULL,
  `set_by_badge` VARCHAR(100) NULL,
  `set_by_name` VARCHAR(255) NULL,
  `set_by_role` VARCHAR(100) NULL,
  `started_at_utc` VARCHAR(50) NULL,
  `ended_at_utc` VARCHAR(50) NULL,
  `duration_seconds` INT NULL,
  `closed_by_badge` VARCHAR(100) NULL,
  `closed_by_name` VARCHAR(255) NULL,
  `closed_by_role` VARCHAR(100) NULL,
  `closed_reason` TEXT NULL,
  `closed_action` VARCHAR(100) NULL,
  `raw_json` JSON NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_machine_status_archive_machine_code` (`machine_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

